const CAM = namespace("CAM");
const CH = namespace("CH");
const CL = namespace("CL");
const DG = namespace("DG");
const KIT = namespace("KIT");
const MO = namespace("MO");
const RIG = namespace("RIG");
const TOON = namespace("TOON");
const TY = namespace("TY");
const UI = namespace("UI");
const SCENES = namespace("SCENES");
const CLIPS = namespace("CLIPS");
const TRANSITIONS = namespace("TRANSITIONS");
const ERAS = namespace("ERAS");
const CLIP = namespace("CLIP");
const TR_UTIL = namespace("TR_UTIL");
    const document = hostDocument;
    const Path2D = capabilities.Path2D;
    const DOMMatrix = capabilities.DOMMatrix;
    const DOMPoint = capabilities.DOMPoint;
    const WIDTH = width, HEIGHT = height, FPS = defaultFps, IMG = assets;
    const FONT_FACES = fonts;
// 拼贴材料 CL（Vox / Missing Chapter / Borders 一路）：纸纹、撕纸边、网点照片、胶带、图钉、红线（下垂的线索绳）、
// 毛边荧光笔（multiply）、轻投影、带倾斜滑入放平、剪纸贴纸白边。
