        c.strokeStyle = '#c23a2a'; c.lineWidth = 2.6; c.beginPath(); c.moveTo(lerp(DISK[0], wx, 0.62), lerp(DISK[1], wy, 0.62)); c.lineTo(wx - Math.cos(ang) * 6, wy - Math.sin(ang) * 6); c.stroke();
