    c.lineWidth = 1.4; for (const [a, b] of [[[fx + 34, fy + 14], [fx + 80, fy + 6]], [[fx + 34, fy + 20], [fx + 78, fy + 26]], [[fx - 34, fy + 16], [fx - 74, fy + 10]], [[fx - 34, fy + 22], [fx - 72, fy + 28]]]) { c.beginPath(); c.moveTo(...a); c.lineTo(...b); c.stroke(); }
