      vines(c, t);
      snail(c, lt, t);
      runMouse(c, lt, t);
      const K = RIG.cat({ tail: ch.tail, blink: ch.blink, breathe: ch.breathe });
      cat(c, K, t, ch);
      const G = RIG.girl({ cup: ch.cup, sip: ch.sip, hair: 'long', breathe: ch.breathe });
      girl(c, G, lt, t, ch);
