    g.fillStyle = vg; g.beginPath(); g.moveTo(410, 366); for (let x = 410; x <= 810; x += 6) g.lineTo(x, 362 + P.noise(x * 0.02, 3) * 4); g.lineTo(810, 545); g.lineTo(410, 545); g.closePath(); g.fill();
