    c.fillStyle = 'rgba(120,70,40,.22)'; c.beginPath(); c.ellipse(G.eye.x + 8, G.eye.y + 2, 14, 9, 0, 0, 7); c.fill(); c.restore();      // 眼窝阴影（晕涂）
    c.fillStyle = SK_D; c.beginPath(); c.ellipse(G.ear[0], G.ear[1], 7, 11, 0.2, 0, 7); c.fill();
