    c.fillStyle = '#5a0c14'; c.beginPath(); c.ellipse(0, 1, 21, 5, 0, 0, 7); c.fill();
    c.fillStyle = 'rgba(255,255,255,.7)'; c.fillRect(-15, 6, 3, 14);
