      c.fillStyle = C.coralDk; c.fillRect(1290, 744, 190, 20); c.restore();
      c.fillStyle = C.coralDk; c.beginPath(); c.roundRect(A.neck[0] - 26, A.neck[1] - 8, 64, 22, 10); c.fill();
      c.restore();
